# set program to vertical reflection r->31-r where in bounds; fallback nearest known column mode for edge/center
path.write_text('def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6:
                rr = 31-r
                if 0 <= rr < h and grid[rr][c] != 6:
                    out[r][c] = grid[rr][c]
                else:
                    vals = [grid[rr][c] for rr in range(h) if grid[rr][c] != 6]
                    out[r][c] = vals[len(vals)//2] if vals else 0
    return out
')
